#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Creates and commits the Knock workflow behind each of Cadence's Notifications.
#
# Knock returns 404 when a workflow that isn't committed is triggered, and a
# workflow's category only exists once the workflow is committed. Workflows
# can only be made in the dashboard, once per Knock environment. Run this for
# each environment, and again whenever a Notification is added. Workflows that
# are already committed just pass their check.
#
#   bash scripts/knock-workflows-wizard.sh                      # Development (.env)
#   ENV_FILE=.env.production bash scripts/knock-workflows-wizard.sh
#
# To add a Notification, append one block to the workflow table in
# run_wizard. Its key and category must match KNOCK_WORKFLOWS and
# KNOCK_CATEGORIES in app/lib/knock.server.ts exactly.

run_wizard() {

cd "$(dirname "$0")/.."

# ── Workflow table: one block per Notification ────────────────────────────
# Each block is "workflow key|category|feed message body". Cadence writes the
# feed row's text from the trigger data, so the body is only what Knock's own
# dashboard previews show. Keep "|" out of it.
WORKFLOWS=()

# Discussion Reply: a reply to someone's Discussion Question → its author.
WORKFLOWS+=("discussion-reply|discussion-replies|**{{ data.replierName }}** replied to your question in {{ data.lessonTitle }}")

# Seat claimed: a Seat on a Team Licence was claimed → the Team Licence's buyer.
WORKFLOWS+=("seat-claimed|seat-claims|**{{ data.claimerName }}** claimed a Seat on {{ data.courseTitle }}. {{ data.seatsLeft }} left.")

# ── End of workflow table ─────────────────────────────────────────────────

TOTAL_STAGES=$(( ${#WORKFLOWS[@]} + 2 ))
KNOCK_API="https://api.knock.app/v1"
DASHBOARD="https://dashboard.knock.app"
PROBE_USER="wizard-probe"

# unquote strips the quotes a value may carry in the env file.
unquote() { sed -e 's/^"//' -e 's/"$//' <<<"$1"; }

# trigger WORKFLOW RECIPIENT prints the HTTP status of a trigger.
trigger() {
  curl -s -o /dev/null -w '%{http_code}' -X POST \
    -H "Authorization: Bearer $KNOCK_SECRET_API_KEY" -H "Content-Type: application/json" \
    -d "{\"recipients\":[{\"id\":\"$2\",\"name\":\"Wizard Check\"}],\"data\":{}}" \
    "$KNOCK_API/workflows/$1/trigger"
}

delete_user() {
  curl -s -o /dev/null -X DELETE \
    -H "Authorization: Bearer $KNOCK_SECRET_API_KEY" "$KNOCK_API/users/$1" || true
}

# check_workflow KEY loops until the workflow is triggerable or the human gives up.
check_workflow() {
  local status
  while true; do
    status=$(trigger "$1" "$PROBE_USER")
    if [[ "$status" == 2* ]]; then
      printf '  %s✓ %s is committed and triggerable%s\n' "$GREEN" "$RESET" "$1"
      return 0
    fi
    warn "triggering $1 returned HTTP $status (404 = missing or not committed)"
    confirm "Fix it in the dashboard, then check again?" || {
      SKIPPED+=("workflow $1 (trigger returned HTTP $status)")
      return 0
    }
  done
}

# workflow_stage KEY CATEGORY BODY walks the human through one workflow.
workflow_stage() {
  stage "Workflow: $1"
  say "Create the ${BOLD}$1${RESET} workflow, or check it if it's already committed."
  open_url "$DASHBOARD"
  step "Check the environment switcher (top left) shows the environment whose keys you entered."
  step "Workflows → Create workflow. Name it '$1'; the key must be exactly: ${BOLD}$1${RESET}"
  step "Categories: add exactly ${BOLD}$2${RESET} (it's the Notification Preference group)."
  step "Save to open the workflow builder."
  step "Add a channel step → In-app feed → the channel with ID ${BOLD}$KNOCK_FEED_CHANNEL_ID${RESET}."
  step "Open the step's template and set the markdown body to:"
  printf '\n      %s%s%s\n\n' "$BOLD" "$3" "$RESET"
  step "Save, then Commit (top right) to this environment."
  note "Labels in the dashboard may differ slightly. What matters is the key, category, channel and commit."
  pause "Press Enter once it's committed, and I'll check it..."
  check_workflow "$1"
  pause "Press Enter to continue"
}

banner "Knock workflows for Cadence's Notifications"

stage "Knock keys for this environment"
say "Workflows are per Knock environment, so first pick the environment's keys."
note "Writing to $ENV_FILE. Press Enter to keep a value that's already there."
open_url "$DASHBOARD"
step "Pick the environment (top left), e.g. Development."
step "Developers → API keys → copy the secret key (starts sk_)."
ask_secret KNOCK_SECRET_API_KEY "Paste the secret API key:"
KNOCK_SECRET_API_KEY=$(unquote "$KNOCK_SECRET_API_KEY")
step "Integrations → Channels → the in-app feed channel → copy its channel ID."
ask KNOCK_FEED_CHANNEL_ID "Paste the feed channel ID:"
KNOCK_FEED_CHANNEL_ID=$(unquote "$KNOCK_FEED_CHANNEL_ID")
if [[ -z "$KNOCK_SECRET_API_KEY" || -z "$KNOCK_FEED_CHANNEL_ID" ]]; then
  printf '  %sBoth values are needed. Re-run the wizard once you have them.%s\n' "$RED" "$RESET"
  exit 1
fi
write_env KNOCK_SECRET_API_KEY "$KNOCK_SECRET_API_KEY"
write_env KNOCK_FEED_CHANNEL_ID "$KNOCK_FEED_CHANNEL_ID"
pause "Press Enter to continue"

for entry in "${WORKFLOWS[@]}"; do
  IFS='|' read -r key category body <<<"$entry"
  workflow_stage "$key" "$category" "$body"
done

stage "Verify every workflow reaches the feed"
if ! command -v jq >/dev/null 2>&1; then
  warn "jq isn't installed, so the feed can't be checked here."
  SKIPPED+=("end-to-end feed check (install jq and re-run)")
else
  VERIFY_USER="wizard-check-$(date +%s)"
  say "Triggering every workflow for a throwaway user ($VERIFY_USER)..."
  for entry in "${WORKFLOWS[@]}"; do
    IFS='|' read -r key _ _ <<<"$entry"
    note "$key → HTTP $(trigger "$key" "$VERIFY_USER")"
  done
  say "Waiting for Knock to deliver (up to ~20s)..."
  for entry in "${WORKFLOWS[@]}"; do
    IFS='|' read -r key _ _ <<<"$entry"
    landed=0
    for _ in $(seq 1 10); do
      landed=$(curl -s -H "Authorization: Bearer $KNOCK_SECRET_API_KEY" \
        "$KNOCK_API/users/$VERIFY_USER/feeds/$KNOCK_FEED_CHANNEL_ID" |
        jq --arg k "$key" '[(.entries // [])[] | select(.source.key == $k)] | length' 2>/dev/null || echo 0)
      [[ "$landed" -ge 1 ]] && break
      sleep 2
    done
    if [[ "$landed" -ge 1 ]]; then
      printf '  %s✓ %s landed in the feed%s\n' "$GREEN" "$key" "$RESET"
    else
      warn "$key did NOT land: check its In-app feed step uses channel $KNOCK_FEED_CHANNEL_ID"
      SKIPPED+=("$key not reaching the feed")
    fi
  done
  delete_user "$VERIFY_USER"
fi
delete_user "$PROBE_USER"
note "Cleaned up the throwaway Knock users."
pause "Press Enter to finish"

finish
}

run_wizard "$@"; exit
